		$event_end  = tribe_get_end_date( $event_id, true, 'U' );
		$current    = current_time( 'timestamp' );

		if ( $event_end < $current ) {
			// Event has ended
			$classes[] = 'past-event';
		} else {
			// Event is upcoming or currently running
			$classes[] = 'upcoming-event';
		}
	}
	return $classes;
});
```

