		if ( ! function_exists( 'tribe_events_product_is_ticket' ) || ! tribe_events_product_is_ticket( $product_id ) ) {
			$all_tickets = false;
			break;
		}
	}

	if ( $all_virtual && $all_tickets ) {
		$order->update_status( 'completed' );
	}
} );
